<script setup lang="ts">
import { computed,ref } from 'vue';
import type { PlannedWeek } from '../domain/models';
import { planThemeWeek } from '../domain/theme-planning';
import { state,scope,change,ui,tags } from '../state';
import { projectSchedule } from '../domain/scout-projection';
const props=defineProps<{week:PlannedWeek;index:number}>();
const theme=ref(String(props.week.theme??(props.week.tags as string[]|undefined)?.[0]??''));
const mode=ref<'progression'|'random'>(props.week.themeMode==='random'?'random':'progression');
const proposed=ref<PlannedWeek|null>(null),baseline=ref('');
const proposedParticipation=computed(()=>{if(!proposed.value)return null;const weeks=[...(state.value!.studio.schedule??[]).slice(0,props.index),proposed.value];return projectSchedule(state.value!.requirements,state.value!.progress.scoutRecords,weeks,state.value!.studio.strategy==='curriculum'?[]:scope.value,{useLocations:true,allowedLocations:(state.value!.studio.allowedLocations??[]) as string[],activities:state.value!.progress.activities??[]})[props.index];});
const themes=computed(()=>[...new Set([...tags.value,...state.value!.requirements.flatMap(r=>(r.theme_tags as string[]|undefined)??[]),...(theme.value?[theme.value]:[])])].sort());
const fingerprint=()=>JSON.stringify({state:state.value,scope:scope.value});
function preview(){try{proposed.value=planThemeWeek(state.value!.requirements,state.value!.progress.scoutRecords,state.value!.studio,scope.value,props.index,theme.value,mode.value,Math.random,state.value!.progress.activities??[]);baseline.value=fingerprint();}catch(e){ui.error=String(e);proposed.value=null;}}
function apply(){if(baseline.value!==fingerprint()){ui.error='Data or Scout scope changed. Preview the themed week again.';proposed.value=null;return;}if(change('Before changing Week '+(props.index+1)+' theme',s=>{s.studio.schedule![props.index]=proposed.value!;}))proposed.value=null;}
</script>
<template><div class="week-theme-controls"><label>Week {{index+1}} theme<select v-model="theme" :aria-label="'Week '+(index+1)+' theme'" @change="proposed=null"><option value="">No theme (clear week)</option><option v-for="t in themes" :key="t">{{t}}</option></select></label><label>Selection method<select v-model="mode" :aria-label="'Week '+(index+1)+' selection method'" @change="proposed=null"><option value="progression">Best for progression</option><option value="random">Random within theme</option></select></label><button @click="preview">Preview themed week</button><section v-if="proposed" class="preview"><h3>Review Week {{index+1}} theme</h3><p>{{proposed.requirementIds.length}} requirements selected for {{theme||'an empty week'}}. Applying locks this week and clears its previous stage activities, attachment and session confirmations. Scout evidence stays unchanged.</p><p v-if="week.locked">This replaces the current locked week's plan only after you apply.</p><ul><li v-for="id in proposed.requirementIds" :key="id"><span v-if="proposed.suggestedRequirementIds?.includes(id)" class="suggestion-badge">Suggested · {{proposed.suggestionThemes?.[id]?.join(', ')}}</span> {{state!.requirements.find(r=>r.id===id)?.text}}<small v-if="scope.length&&state!.studio.strategy!=='curriculum'" class="requirement-assignees">{{proposedParticipation?.requirementScouts[id]?.join(', ')||'No Scouts assigned'}}</small></li></ul><p v-for="stage in [1,2,3]" :key="stage" class="stage-shortfall"><template v-if="proposed.stageShortfalls?.[String(stage)]">Stage {{stage}}: {{proposed.stageShortfalls[String(stage)]}} short of target; no more distinct, related, location-compatible statements are available.</template></p><button @click="apply">Apply theme and lock week</button><button @click="proposed=null">Cancel theme change</button></section></div></template>
